$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "(?m)^#root #pausebox > div:has\(> #resumebtn\) > #fbbtn, #root #pausebox > div:has\(> #resumebtn\) > #wnbtn\{ color:var\(--tx-1\); \}"
$r1=@'
#root #pausebox > div:has(> #resumebtn) > #fbbtn, #root #pausebox > div:has(> #resumebtn) > #wnbtn{ color:var(--tx-1); }
/* v28.xx (cw-pausebtn) critic on the pause box 25, 42, 49 (3 each): "feedback, what is new and abandon are 40px strips, too small to hit and too quiet next to resume". Now: those buttons are 48px high (the small button size), abandon keeps no box (an older check) and sits 16px under the row. Q61 keeps the feedback and what is new buttons. */
#root #pausebox > div:has(> #resumebtn) > #fbbtn, #root #pausebox > div:has(> #resumebtn) > #wnbtn{ min-height:var(--btn-h-sm); font-size:var(--fs-body); }
#root #pausebox:not(.asking) > div:has(> #resumebtn) > #abandonbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #arcendbtn, #root #pausebox:not(.asking) > div:has(> #resumebtn) > #charselbtn{ min-height:var(--btn-h-sm); margin-top:var(--sp-3); }
'@.Replace("`r",'').TrimEnd("`n")
$chk=@'
  {v:'VER',what:'the pause box feedback, what is new and abandon buttons are 48px high (the small button size), not 40',
   run:function(){
     var want={fbbtn:0,wnbtn:0,abandonbtn:0}, ss=document.styleSheets, i, j, r, k;
     for(i=0;i<ss.length;i++){ var rules; try{ rules=ss[i].cssRules; }catch(_e){ continue; }
       for(j=0;j<rules.length;j++){ r=rules[j]; if(!r.selectorText||!r.style) continue;
         if(r.style.minHeight!=='var(--btn-h-sm)') continue;
         for(k in want){ if(r.selectorText.indexOf('#'+k)>=0&&r.selectorText.indexOf('#pausebox')>=0) want[k]=1; } } }
     for(k in want){ if(!want[k]) return 'no 48px (btn-h-sm) rule for #'+k+' in the pause box'; }
     return null;
   }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='Pause box feedback, what is new and abandon buttons at 48px'
  why='Critic on the pause box screens 25, 42 and 49 (3 each) called the 40px feedback, what is new and abandon strips too small and too quiet. They move to the 48px small button size with 16px body text. Nothing is removed (Q61).'
  now='The pause box feedback, what is new and abandon buttons are taller.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-pausebtn.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
